function makeWallet(coins) {
  const spend = (n) => {
    coins -= n;
  };

  return [spend, () => coins];
}

let pocket = 10;
const [spend, left] = makeWallet(pocket);

pocket = 50;
spend(3);

const [, leftB] = makeWallet(pocket);

spend(1);
console.log(left());
console.log(pocket);
console.log(leftB());
